function mifflin(w, h, a, sex){ return 10*w + 6.25*h - 5*a + ((sex==='F'||sex==='f')? -161 : 5); }
function harris(w, h, a, sex){ return 88.362 + 13.397*w + 4.799*h - 5.677*a + ((sex==='F'||sex==='f')? -161 : 5); }
function tdee(bmr, factor){ factor=(factor==null)?1.2:factor; return bmr*factor; }
var EXPORTS={ mifflin:mifflin, harris:harris, tdee:tdee };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BmrForgePure = EXPORTS; }
